// A real render of the real "Keys" tab in js/pages/account.js -- closes
// the gap named honestly in fxn-auth's own CLAUDE.md: the UI existed,
// was syntax-checked and selector-cross-checked, but had never been
// exercised through a real click in a real DOM. Same jsdom+real-bundle
// pattern flux-launchpad's auth.dom.live-unlock.test.mjs already
// established (real WebCrypto via node:crypto's webcrypto.subtle, since
// jsdom ships getRandomValues but not SubtleCrypto at all), reusing that
// exact fixture (a real, complete v9 Auth Kit generated by actually
// running ark-dao's own createRecoveryIdentity(); disposable test
// credentials, no value behind it) rather than building a second one.
//
// `account.js` is a much larger surface than flux-launchpad's `auth.mjs`
// wrapper (930+ lines, cross-cutting `ArkUI.meshDirectory`/`cmsSession`/
// `localIdentity`). Rather than mock all of it, this gives it the SAME
// minimal `ArkUI` bootstrap a real page would (each real module does
// `window.ArkUI = window.ArkUI || {}` defensively) -- `localIdentity` is
// stubbed with real no-op methods (account.js calls it unconditionally);
// `cmsSession`/`meshDirectory` are left undefined, which account.js's own
// code already guards with `if (ArkUI.cmsSession)`/`if (window.ArkUI &&
// window.ArkUI.meshDirectory)` -- confirmed by reading those call sites
// directly, not assumed.
import assert from 'node:assert/strict';
import test from 'node:test';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
// jsdom is this site's own dev dependency. The import named the Mac's sibling launchpad checkout, so on a build node
// (or any machine laid out differently) the file failed to load before a test ran.
import { JSDOM } from 'jsdom';
import { webcrypto } from 'node:crypto';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const BUNDLE_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'admin', 'auth.js'), 'utf8');
const ACCOUNT_PAGE_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'pages', 'account.js'), 'utf8');
// The real Scoped Claim Authorization dialog's own dependency chain, same
// files and same order as js/pages/catalog.js's real `account` route
// loads them (minus ml-dsa.js/auth-kit-create-panel.js/mesh-directory-
// client.js/local-domains.js, unrelated to what this test exercises) --
// closes a real gap the previous round of this test left open: every
// Keys-tab action (add/rotate/revoke/delegate) is a signing surface that
// now routes through `window.ArkUI.authorizationDialog.confirm(...)`
// before signing (see js/pages/account.js's `confirmWalletAction`), but
// this test's jsdom never loaded the dialog's own dependencies, so
// `confirmWalletAction`'s own `if (!(window.ArkUI.authorizationDialog...))
// return Promise.resolve(true)` fallback silently auto-approved every
// action -- the suite passed 5/5 without the dialog ever existing, let
// alone being clicked. Found by reading the account.js wiring itself
// against what this test's jsdom actually had loaded, not guessed.
const DIRECTORY_TRANSPORT_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'ark', 'directory-transport.js'), 'utf8');
const ED25519_PEM_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'ark', 'ed25519-pem-browser.js'), 'utf8');
const FLUX_ELEMENTS_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'admin', 'vendor', 'flux-elements.js'), 'utf8');
const AUTHORIZATION_VIEW_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'admin', 'authorization-view.js'), 'utf8');
const AUTHORIZATION_DIALOG_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'ark', 'authorization-dialog.js'), 'utf8');
const DASH_KIT_SOURCE = fs.readFileSync(path.join(HERE, '..', 'js', 'ark', 'dash-kit.js'), 'utf8');
const KIT_PIN = '13572468';
const KIT_PASSWORD = 'launchpad-test';
/* Round 14: an FXN ID signs only as one of its Public IDs, and a file with none cannot sign in on /account ("This
   identity has no valid public identifier to remember"). The v9 fixture predates the Public ID block, so the test
   gives it one with fxn-auth's own addPublicId and writes the new file with the kit's own envelope encoder: the same
   file a person gets after adding one under Public IDs. Its root, phrase, PIN and password are the fixture's. */
const V9_TEXT = fs.readFileSync(new URL('../../flux-launchpad/js/fixtures/real-auth-kit-v9.flx', import.meta.url), 'utf8');
const { unlockPortableAuthKit } = await import('../../fxn-auth/src/authKitMigration.mjs');
const { addPublicId } = await import('../../fxn-auth/src/publicIds.mjs');
const fromFxnAuth = createRequire(new URL('../../fxn-auth/package.json', import.meta.url));
const { encodeAuthKitEnvelope } = await import(pathToFileURL(fromFxnAuth.resolve('@deadark/ark-ui/flux-auth')).href);
const V9_OPENED = await unlockPortableAuthKit({ authKit: V9_TEXT, pin: KIT_PIN, password: KIT_PASSWORD });
const REAL_KIT_TEXT = encodeAuthKitEnvelope((await addPublicId(V9_OPENED.kit, V9_OPENED.secret.mnemonic, { label: 'DOM test' })).vault);

/* Every wait in this file polls for the state the next step depends on; none
   sleeps a fixed time and then reads whatever is there.

   Why (regression, diagnosed 2026-10-18): this file used fixed sleeps --
   2500 ms after sign-in, 2000 ms after each approval -- and then read the
   result line. It failed intermittently with "Adding…"/"Rotating…" (the
   action simply had not finished) and once with "No such wallet on this
   identity" on the FIRST revoke. That second one was not a product race: the
   revoke test copied its address out of the add result with
   `.replace('Added ', '')`, so a still-running add handed the literal string
   "Adding…" to Revoke, and the library correctly refused an address it does
   not hold. Measured on the owner's Apple M2 Mac mini (8 cores, 8 GB, ~8.7 GB
   swap in use), load average 25-28, 3 full runs: sign-in 0.6-3.4 s, add
   0.35-2.4 s, rotate 0.3-1.2 s, revoke 26-122 ms -- so 3 of 27 waits overran
   their fixed sleep. Polling makes the test wait exactly as long as the work
   takes, and the add result is asserted to BE an address before anything uses
   it, so a slow add can never again masquerade as a wrong refusal. The
   deadline only separates "slow" from "never finishes". */
const SETTLE_DEADLINE_MS = 30000;
async function until(read, what, timeoutMs = SETTLE_DEADLINE_MS) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const value = read();
    if (value) return value;
    if (Date.now() > deadline) throw new Error(`timed out after ${timeoutMs} ms waiting for ${typeof what === "function" ? what() : what}`);
    await new Promise((resolve) => setTimeout(resolve, 25));
  }
}
// A result line is settled once it is non-empty and not a progress message
// ("Adding…", "Rotating…", "Revoking…", "Delegating…" all end in an ellipsis).
function settledText(node, what) {
  return until(() => { const text = node.textContent; return text && !/…$/.test(text) ? text : null; }, what);
}

const tabNamed = (page, name) => [...page.querySelectorAll('[role="tab"]')].find((tab) => tab.textContent.trim() === name);
const openTab = (dom, page, name) => tabNamed(page, name).dispatchEvent(new dom.window.Event('click', { bubbles: true }));

function setInputValue(window, input, value) {
  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  nativeSetter.call(input, value);
  input.dispatchEvent(new window.Event('input', { bubbles: true }));
}

function mountAccountPage() {
  const dom = new JSDOM('<!doctype html><html><body><div id="host"></div></body></html>', {
    url: 'http://localhost/', runScripts: 'dangerously', pretendToBeVisual: true,
  });
  Object.defineProperty(dom.window.crypto, 'subtle', { value: webcrypto.subtle, configurable: true });
  // jsdom's window has no `structuredClone` (a real gap in its own global
  // surface, found by running this test, not guessed) -- the real bundle
  // uses it to deep-clone the vault object on every mutation. Node's own
  // global `structuredClone` is spec-identical; this is a missing jsdom
  // API, not a mock of any app behavior.
  dom.window.structuredClone = structuredClone;
  /* The page as it loads in a browser (W4-S2, 2026-10-20): /account is Ark blocks, so the runtime, the Ark kit and
     the blocks adapter load first, in the order js/pages/catalog.js lists them -- and the REAL local-identity
     store, not a stub. The stub this file used to carry passed the full signer object through as the page's
     identity, which is why the Keys view looked fine here while it was inert in a real browser (the real store keeps
     six public fields; the wallet list and methods live on the signer; tests/browser/account-flows.mjs step 9 found
     it). With the real store this file is the proof the Keys actions work. */
  const w = dom.window;
  w.matchMedia = () => ({ matches: false, addEventListener() {}, removeEventListener() {} });
  w.eval("var ArkCopy = { isKey: function () { return false; }, resolve: function (v) { return v; }, text: function (k) { throw new Error('no copy key ' + k); } };");
  const run = (source) => { const script = w.document.createElement('script'); script.textContent = source; w.document.body.appendChild(script); };
  for (const file of ['js/ark/atomizer.js', 'js/ark/flux.js', 'js/ark/runtime.js', 'js/ark/vendor/engines.js']) run(fs.readFileSync(path.join(HERE, '..', file), 'utf8'));
  w.eval("ArkUI.pageCatalog = { account: { path: '/account' }, 'account/domains': { path: '/account/domains' }, bundledeployer: { path: '/bundle-deployer' }, explorer: { path: '/explore' }, zero: { path: '/' } }; ArkUI.route = { href: function (p) { return p; } }; ArkUI.pageModules = {};");
  const blockScripts = JSON.parse(/ArkUI\.blockScripts = (\[[^\]]+\]);/.exec(fs.readFileSync(path.join(HERE, '..', 'js', 'pages', 'catalog.js'), 'utf8'))[1].replace(/'/g, '"'));
  for (const file of blockScripts.filter((f) => f !== 'js/ark/dash-kit.js').concat(['js/ark/vendor/ark-kit-forms.js'])) run(fs.readFileSync(path.join(HERE, '..', file), 'utf8'));
  // js/ark/account-session.js: the one sign-in session, moved out of js/pages/account.js on 2026-10-25 (catalog.js loads it before the page).
  for (const file of ['js/ark/local-identity.js', 'js/ark/local-domains.js', 'js/ark/account-session.js']) run(fs.readFileSync(path.join(HERE, '..', file), 'utf8'));
  const liveChunk = fs.readFileSync(path.join(HERE, '..', 'js', 'ark', 'vendor', 'ark-kit-live.js'), 'utf8');
  w.ArkUI.loadScript = () => Promise.resolve().then(() => w.eval(liveChunk)); // the first ArkUI.blocks.update loads Ark's live chunk, as js/ark/page-loader.js does
  for (const source of [BUNDLE_SOURCE, DIRECTORY_TRANSPORT_SOURCE, ED25519_PEM_SOURCE, FLUX_ELEMENTS_SOURCE, AUTHORIZATION_VIEW_SOURCE, AUTHORIZATION_DIALOG_SOURCE, DASH_KIT_SOURCE, ACCOUNT_PAGE_SOURCE]) run(source);
  const host = dom.window.document.getElementById('host');
  const page = dom.window.ArkUI.pageModules.account.mount(host);
  return { dom, host, page };
}

// Waits for the real `<flux-authorization-dialog>` to actually appear
// (its view is built asynchronously -- `confirmWalletAction` awaits a
// real `sha256HexOfText` digest first) and clicks its real "Approve
// scopes & sign" button, matching the exact text this real component
// renders (js/ark/authorization-dialog.js's `h('button', ..., text:
// 'Approve scopes & sign')`) -- the same button a real browser test
// (this session's flux-launchpad verification) already clicked by name.
async function approveAuthorizationDialog(dom, { timeoutMs = SETTLE_DEADLINE_MS } = {}) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const dialog = dom.window.document.querySelector('flux-authorization-dialog');
    if (dialog) {
      const approve = [...dialog.querySelectorAll('button')].find((b) => b.textContent === 'Approve scopes & sign');
      if (approve) { approve.click(); return true; }
    }
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  return false;
}

async function selectKitFile(dom, container, text, filename = 'real.flx') {
  const fileInput = container.querySelector('input[type="file"]');
  const file = new dom.window.File([text], filename, { type: 'application/vnd.flux.auth-kit' });
  Object.defineProperty(fileInput, 'files', { value: [file], configurable: true });
  fileInput.dispatchEvent(new dom.window.Event('change', { bubbles: true }));
  // the kit is parsed asynchronously; its unlock form appears once it has been
  await until(() => container.querySelector('[data-ark-auth="field-pin"]'), 'the Auth Kit unlock form after choosing the kit file');
}

async function signIn(dom, page) {
  const authContainer = page.querySelector('[data-account-auth]');
  await selectKitFile(dom, authContainer, REAL_KIT_TEXT);
  // Round 14: the panel asks one field per step (PIN, then password), with Next between them and Unlock on the last.
  const step = async (name, value) => {
    const field = await until(() => authContainer.querySelector(`[data-ark-auth="field-${name}"]`), `the ${name} step`);
    setInputValue(dom.window, field, value);
    authContainer.querySelector('[data-ark-auth="form"]').dispatchEvent(new dom.window.Event('submit', { bubbles: true, cancelable: true }));
  };
  await step('pin', KIT_PIN);
  await step('password', KIT_PASSWORD);
  // account.js's renderIdentity() marks the page 'verified-local' once the
  // identity is signed in AND unlocked -- the state the Keys tab requires.
  await until(() => page.dataset.session === 'verified-local', () => `the account page to reach the signed-in, unlocked state (it is ${page.dataset.session || 'unset'}; the panel says: ${authContainer.querySelector('[data-ark-auth="notice"]')?.textContent || authContainer.querySelector('[data-ark-auth="heading"]')?.textContent || 'nothing'})`);
}

test('the real "Signing keys" tab becomes available after a real sign-in, and lists the real wallet already on the kit', async () => {
  const { dom, page } = mountAccountPage();
  await signIn(dom, page);

  const keysTab = tabNamed(page, 'Signing keys');
  assert.ok(keysTab, 'the Signing keys tab must exist once a real identity is signed in and unlocked');

  openTab(dom, page, 'Signing keys');
  const panel = page.querySelector('[data-account-panel="keys"]');
  assert.equal(keysTab.getAttribute('aria-selected'), 'true', 'clicking the real tab must select it');
  assert.equal(panel.closest('[role="tabpanel"]').hidden, false, 'and show the real Keys panel');

  const list = panel.querySelector('#account-keys-list');
  assert.match(list.textContent, /d43kkms26scspdyq92r3fhgmf1kefxra7xcr5vqa62qghh7fdqsmcdczwnm0/, 'the real wallet address already on this kit must appear in the real rendered list');
});

test('clicking the real "Add wallet" button genuinely mints a private wallet on the Public ID in use, and the list updates live, with no re-sign-in', async () => {
  const { dom, page } = mountAccountPage();
  await signIn(dom, page);
  openTab(dom, page, 'Signing keys');

  const panel = page.querySelector('[data-account-panel="keys"]');
  const list = panel.querySelector('#account-keys-list');
  const before = list.textContent;
  setInputValue(dom.window, panel.querySelector('#account-keys-add [name="label"]'), 'DOM Test Wallet');
  panel.querySelector('#account-keys-add').dispatchEvent(new dom.window.Event('submit', { bubbles: true, cancelable: true }));
  const approved = await approveAuthorizationDialog(dom);
  assert.ok(approved, 'the real Scoped Claim Authorization dialog must appear before a wallet is minted -- every signing surface shows it, this one is no exception');

  // Round 14 (owner ruling, option A): a new wallet belongs to the Public ID in use, signed by the wallet and that
  // Public ID, and stays private in the file. The result names its key's first 12 hex digits.
  const result = await settledText(panel.querySelector('#account-keys-add-result'), 'the add-wallet result');
  const added = /^Added private wallet ([0-9a-f]{12})\u2026\. Save the new file now/.exec(result);
  assert.ok(added, `the real add-wallet result must show success, got: ${result}`);
  assert.doesNotMatch(before, new RegExp(added[1]), 'the new wallet must be a genuinely new key, not one already listed');

  // The list re-renders from the SAME identity object (the live getter), with no new sign-in.
  const row = [...list.querySelectorAll('.ark-list__row')].find((li) => li.textContent.includes(added[1]));
  assert.ok(row, 'the newly-minted wallet must appear in the list immediately, with no re-sign-in');
  assert.match(row.textContent, /[0-9a-f]{64}/, 'listed by its whole 64-hex key');
  assert.match(row.textContent, /Wallet of /, 'as a wallet of the Public ID in use');
  assert.match(row.textContent, /Private/, 'and private until its link is published');
  assert.match(list.textContent, new RegExp(DEFAULT_ADDRESS), 'the older wallet must still be listed too -- history, never overwritten');
});

const DEFAULT_ADDRESS = 'd43kkms26scspdyq92r3fhgmf1kefxra7xcr5vqa62qghh7fdqsmcdczwnm0';

/* Rotate one of the file's older wallets (made by the Master ID inside the file) and return the rotated-to address. */
async function rotateOlder(dom, panel, address, label) {
  setInputValue(dom.window, panel.querySelector('[data-account-keys-pin]'), KIT_PIN);
  setInputValue(dom.window, panel.querySelector('[data-account-keys-password]'), KIT_PASSWORD);
  setInputValue(dom.window, panel.querySelector('#account-keys-action [name="address"]'), address);
  setInputValue(dom.window, panel.querySelector('#account-keys-action [name="rotateLabel"]'), label);
  panel.querySelector('#account-keys-action').dispatchEvent(new dom.window.Event('submit', { bubbles: true, cancelable: true }));
  assert.ok(await approveAuthorizationDialog(dom), 'the real Scoped Claim Authorization dialog must appear before a wallet is rotated');
  const result = await settledText(panel.querySelector('#account-keys-action-result'), 'the rotate result');
  assert.match(result, new RegExp('^Rotated ' + address + ' \u2192 \\S+$'), `the real rotate result must show success, got: ${result}`);
  return result.split('\u2192')[1].trim();
}

test('clicking the real "Rotate" button genuinely supersedes an older wallet with a new key, and both stay listed', async () => {
  const { dom, page } = mountAccountPage();
  await signIn(dom, page);
  openTab(dom, page, 'Signing keys');
  const panel = page.querySelector('[data-account-panel="keys"]');

  const newAddress = await rotateOlder(dom, panel, DEFAULT_ADDRESS, 'DOM Rotated');
  assert.notEqual(newAddress, DEFAULT_ADDRESS, 'the rotated-to wallet is a new key');

  const list = panel.querySelector('#account-keys-list');
  const rowOf = (address) => [...list.querySelectorAll('.ark-list__row')].find((li) => li.textContent.includes(address));
  assert.ok(rowOf(newAddress), 'the rotated-to address must appear in the list immediately');
  assert.ok(rowOf(DEFAULT_ADDRESS), 'the superseded address stays in the list -- history, never overwritten');
  // Round 14: with Public IDs, the file's own wallets are listed as older wallets. The Public ID in use is what signs.
  for (const address of [newAddress, DEFAULT_ADDRESS]) assert.match(rowOf(address).textContent, /Older wallet, made by your Master ID/);
  // Law 10: `identity.walletAddress` is a live getter, so the "Default" marker moves to the NEW address.
  assert.match(rowOf(newAddress).textContent, /Default/, 'the default marker must move to the rotated-to address');
  const oldLine = [...list.querySelectorAll('.ark-list__row')].find((li) => li.textContent.includes(DEFAULT_ADDRESS) && !li.textContent.includes(newAddress));
  assert.doesNotMatch(oldLine.textContent, /Default/, 'the superseded address must no longer be marked as default');
});

test('clicking the real "Revoke" button genuinely retires a wallet, recorded in the real vault', async () => {
  const { dom, page } = mountAccountPage();
  await signIn(dom, page);
  openTab(dom, page, 'Signing keys');
  const panel = page.querySelector('[data-account-panel="keys"]');

  // A second older wallet first (Revoke acts on the file's own wallets, and a new wallet on the Public ID is not one):
  // rotating gives one, and the test then retires that, never the file's original wallet.
  const addedAddress = await rotateOlder(dom, panel, DEFAULT_ADDRESS, 'ToRevoke');

  const actionResult = panel.querySelector('#account-keys-action-result');
  actionResult.textContent = '';
  setInputValue(dom.window, panel.querySelector('#account-keys-action [name="address"]'), addedAddress);
  panel.querySelector('[data-action="keys-revoke"]').click();
  assert.ok(await approveAuthorizationDialog(dom), 'the real Scoped Claim Authorization dialog must appear before a wallet is revoked');

  const result = await settledText(actionResult, 'the revoke result');
  assert.match(result, new RegExp('^Revoked ' + addedAddress), `the real revoke result must show success, got: ${result}`);
  actionResult.textContent = ''; // so the second attempt's own outcome is what gets read, not this one

  // Re-revoking the same (now-dead) address is refused by the real
  // library -- clicking Revoke again must surface that failure, not
  // silently "succeed" a second time. The dialog still appears (approval
  // gates the library call, which is the thing that then refuses it).
  panel.querySelector('[data-action="keys-revoke"]').click();
  assert.ok(await approveAuthorizationDialog(dom), 'the dialog must appear again for the second revoke attempt too');
  assert.match(await settledText(actionResult, 'the second revoke result'), /No such wallet on this identity/, 're-revoking an already-revoked wallet through the real UI must surface the real refusal, not silently succeed');
});

test('clicking the real "Delegate to identity" then "Revoke delegation" buttons genuinely create and revoke a real signed grant', async () => {
  const { dom, page } = mountAccountPage();
  await signIn(dom, page);
  openTab(dom, page, 'Signing keys');
  const panel = page.querySelector('[data-account-panel="keys"]');

  setInputValue(dom.window, panel.querySelector('#account-keys-action [name="address"]'), DEFAULT_ADDRESS);
  panel.querySelector('[data-action="keys-delegate"]').click();
  assert.ok(await approveAuthorizationDialog(dom), 'the real Scoped Claim Authorization dialog must appear before delegating a wallet');

  const actionResult = panel.querySelector('#account-keys-action-result');
  let result = await settledText(actionResult, 'the delegate result');
  assert.match(result, /^Delegated receive\+spend to this identity$/, `the real delegate result must show success, got: ${result}`);

  // The real, signed delegation now appears in the live list via `identity.walletDelegations` (a live getter). Law 10:
  // with Public IDs too, the older wallet's row says it is delegated.
  let list = panel.querySelector('#account-keys-list');
  const delegatedLine = [...list.querySelectorAll('.ark-list__row')].find((li) => li.textContent.includes(DEFAULT_ADDRESS));
  assert.match(delegatedLine.textContent, /delegated to identity/);

  actionResult.textContent = ''; // read the revoke's own outcome, not the delegate line above
  panel.querySelector('[data-action="keys-revoke-delegation"]').click();
  assert.ok(await approveAuthorizationDialog(dom), 'the real dialog must appear before revoking the delegation too');
  result = await settledText(actionResult, 'the revoke-delegation result');
  assert.match(result, new RegExp('^Revoked the delegation for ' + DEFAULT_ADDRESS));

  list = panel.querySelector('#account-keys-list');
  const revokedLine = [...list.querySelectorAll('.ark-list__row')].find((li) => li.textContent.includes(DEFAULT_ADDRESS));
  assert.match(revokedLine.textContent, /delegation revoked/, 'the live list must reflect the real revoked-delegation state immediately');
});
